import{a as e,i as t,r as n,t as r}from"./app-Df0mTKG8.js";var i=JSON.parse(`{"path":"/guide/maimai.html","title":"舞萌 DX（maimai）","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790405684000,"contributors":[{"name":"ShiroMizu","username":"ShiroMizu","email":"ShiroMizuTan@163.com","commits":6,"url":"https://github.com/ShiroMizu"}],"changelog":[{"hash":"44ddac8ae97e55ade0c80cba0123eead160887e7","time":1790405684000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add sauce page, sync arcade prefixless and maimai updates"},{"hash":"773bd574bdd7c9d39c1352376ce7928c3358afb3","time":1787771416000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: sync with latest COMMANDS.md"},{"hash":"3a2020b47139cbd549e92f2b43b5477ec3da578a","time":1787575055000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: update documentation"},{"hash":"dbbebf0ae52d8c28e10f200fce06754b198aabca","time":1787427868000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: update documentation"},{"hash":"57546f95c134385650dbbd8372628b2b1fe87567","time":1787310720000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: update maimai documentation"},{"hash":"c8f72ace24131d7692aae7675d3b3f124a3351ad","time":1787271196000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add maimai documentation"}]},"filePathRelative":"guide/maimai.md"}`),a={name:`maimai.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="舞萌-dx-maimai" tabindex="-1"><a class="header-anchor" href="#舞萌-dx-maimai"><span>舞萌 DX（maimai）</span></a></h1><p>以下功能查询舞萌 DX 曲库、谱面、玩家成绩和牌子进度。所有指令都需要使用 <code>.</code> 前缀；歌曲名、用户名等包含空格的参数可使用中文引号包裹。</p><h2 id="曲库与谱面" tabindex="-1"><a class="header-anchor" href="#曲库与谱面"><span>曲库与谱面</span></a></h2><table><thead><tr><th>指令 / 格式</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>查歌</code></td><td><code>歌名 [页码]</code></td><td><code>.查歌 初音</code></td><td>按歌名搜索；结果较少时直接列出，单曲时发送谱面信息卡，结果较多时发送分页图片</td></tr><tr><td><code>定数查歌</code></td><td><code>定数</code> / <code>最小定数 最大定数 [页码]</code>；或带 <code>+</code> 的等级</td><td><code>.定数查歌 13.7</code> 或 <code>.定数查歌 13+</code></td><td>按谱面定数搜索；<code>13+</code> 这类带 <code>+</code> 的写法按难度等级匹配</td></tr><tr><td><code>bpm查歌</code></td><td><code>BPM</code> / <code>最小BPM 最大BPM [页码]</code></td><td><code>.bpm查歌 180 200</code></td><td>按 BPM 搜索歌曲</td></tr><tr><td><code>曲师查歌</code></td><td><code>曲师名 [页码]</code></td><td><code>.曲师查歌 某某</code></td><td>按作曲 / 曲师搜索歌曲</td></tr><tr><td><code>谱师查歌</code></td><td><code>谱师名 [页码]</code></td><td><code>.谱师查歌 某某</code></td><td>按谱面设计者搜索歌曲</td></tr><tr><td><code>&lt;别名&gt;是什么歌</code> / <code>&lt;别名&gt;是啥歌</code></td><td><code>[页码]</code></td><td><code>.绿谱是什么歌</code></td><td>查询歌曲别名；别名重复时列出歌曲 ID</td></tr><tr><td><code>id</code></td><td><code>歌曲 ID</code></td><td><code>.id 12345</code></td><td>按歌曲 ID 查询谱面信息卡</td></tr><tr><td><code>minfo</code> / <code>Minfo</code> / <code>info</code></td><td><code>歌曲 ID / 歌名 / 别名</code></td><td><code>.minfo 12345</code></td><td>查询自己的指定歌曲成绩；需要已绑定水鱼账号</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p><code>查歌</code> 的类型也可以写作 <code>定数查歌</code>、<code>bpm查歌</code>、<code>曲师查歌</code>、<code>谱师查歌</code>。歌曲列表每页最多 25 首；谱面信息卡会显示曲名、作者、BPM、版本、难度、谱师和物量等信息。</p></div><h2 id="玩家成绩与账号绑定" tabindex="-1"><a class="header-anchor" href="#玩家成绩与账号绑定"><span>玩家成绩与账号绑定</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>b50</code> / <code>B50</code></td><td><code>[水鱼用户名]</code></td><td><code>.b50</code> 或 <code>.b50 玩家名</code></td><td>查询自己的 Best 50；也可指定水鱼用户名（用户名查询仅水鱼支持）</td></tr><tr><td><code>ap50</code> / <code>AP50</code></td><td>无</td><td><code>.ap50</code></td><td>查询自己的 AP50；<strong>仅落雪查分器支持</strong>，需先用 <code>.绑定落雪</code> 完成授权</td></tr><tr><td><code>绑定水鱼</code> / <code>水鱼绑定</code> / <code>bindmaimai</code></td><td>无</td><td><code>.绑定水鱼</code></td><td>生成水鱼 OAuth 绑定链接；链接有效期 10 分钟</td></tr><tr><td><code>绑定落雪</code> / <code>落雪绑定</code> / <code>bindlxns</code></td><td>无</td><td><code>.绑定落雪</code></td><td>生成落雪 OAuth 授权链接（权限：读取玩家数据）</td></tr><tr><td><code>数据源</code> / <code>maimai数据源</code></td><td><code>自动/水鱼/落雪</code></td><td><code>.数据源 落雪</code></td><td>设置自己的数据源偏好</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>玩家成绩相关指令默认使用发送者 QQ；实际 @ 用户时查询被 @ 用户的 QQ。未绑定、用户不存在、拒绝授权、接口限流或服务异常时会返回对应提示。</p><p>数据源偏好（按用户独立存储，仅影响自己的查询）：</p><ul><li><code>自动</code>（默认）：水鱼优先，失败自动切换落雪</li><li><code>水鱼</code>：查询优先使用水鱼查分器</li><li><code>落雪</code>：查询优先使用落雪查分器</li></ul><p>当实际使用的数据源与偏好不一致时，BOT 会在回复中提示实际来源。</p><p><strong>AP50 与牌子查询没有备选数据源</strong>（AP50 仅落雪、牌子仅水鱼），不受数据源偏好影响。</p></div><h2 id="谱面推荐" tabindex="-1"><a class="header-anchor" href="#谱面推荐"><span>谱面推荐</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>推荐</code> / <code>rec</code></td><td><code>[模式] [数量]</code></td><td><code>.推荐</code>、<code>.推荐 擦边</code>、<code>.推荐 补完 20</code></td><td>推荐接下来值得打的谱面；数量 1–30，默认 15</td></tr></tbody></table><p>推荐基于你的 B50 成绩计算「打到下一评价档」的收益，六个模式的候选集互不重叠：</p><table><thead><tr><th>模式</th><th>说明</th></tr></thead><tbody><tr><td><code>吃分</code>（默认）</td><td>已游玩、推到 SSS（100）/ SSS+（100.5）收益最大的谱面，按有效差距升序</td></tr><tr><td><code>擦边</code></td><td>已游玩、距 SSS / SSS+ 不足 0.5% 的谱面，按差距从小到大</td></tr><tr><td><code>水分</code></td><td>定数高于拟合定数的谱面（比标称好打、给分却按定数算），按差值从大到小</td></tr><tr><td><code>新歌</code></td><td>只算当前版本新曲（记入 B15），推到 SSS/SSS+ 收益最大的</td></tr><tr><td><code>旧曲</code></td><td>只算非当前版本谱面（记入 B35），推到 SSS/SSS+ 收益最大的</td></tr><tr><td><code>补完</code></td><td>完全没打过、难度落在 B50 定数中位数 ±1.0 的谱面，按打完的 B50 预期增量降序</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>rating 只在评价档跳变时增长，所以推荐目标永远是「推到下一档」而不是某个百分比。增量统一按 B50 边际计算：已在榜内的谱面减自身当前值，不在榜内的减门槛值。</p></div><h2 id="定数表与完成表" tabindex="-1"><a class="header-anchor" href="#定数表与完成表"><span>定数表与完成表</span></a></h2><table><thead><tr><th>指令 / 格式</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>&lt;等级&gt;定数表</code></td><td>等级 <code>7</code> 至 <code>15</code>（可带 <code>+</code>）</td><td><code>.13+定数表</code></td><td>发送指定等级的定数表；低于 7 的等级不支持</td></tr><tr><td><code>&lt;等级&gt;[fc/fc+/ap/ap+]完成表</code></td><td>等级 <code>7</code> 至 <code>15</code>，可选完成计划</td><td><code>.13ap完成表</code></td><td>查询指定等级的成绩完成表；可选 FC / AP 计划</td></tr><tr><td><code>&lt;版本&gt;&lt;牌子&gt;完成表</code></td><td>版本 + 牌子 + 可选页码</td><td><code>.紫将完成表</code></td><td>查询指定版本牌子完成表</td></tr><tr><td><code>&lt;版本&gt;&lt;牌子&gt;进度表</code></td><td>版本 + 牌子 + 可选页码</td><td><code>.紫将进度</code></td><td>查询指定版本牌子进度</td></tr><tr><td><code>&lt;等级&gt; &lt;评价&gt;进度</code></td><td>等级、评价、可选分类和页码</td><td><code>.13 s 进度</code></td><td>查询指定等级的评价进度</td></tr><tr><td><code>&lt;定数&gt;分数列表</code></td><td>定数 + 可选页码</td><td><code>.13.0分数列表</code></td><td>查询指定定数的分数列表</td></tr></tbody></table><h3 id="牌子版本与评价" tabindex="-1"><a class="header-anchor" href="#牌子版本与评价"><span>牌子版本与评价</span></a></h3><div class="hint-container tip"><p class="hint-container-title">提示</p><p>牌子版本支持真、超、檄、橙、暁/晓、桃、櫻/樱、紫、菫/堇、白、雪、輝/辉、舞、霸、熊、華/华、爽、煌、宙、星、祭、祝、双、宴、镜、彩等写法。牌子计划常用 <code>者</code>、<code>極/极</code>、<code>将</code>、<code>神</code>、<code>舞舞</code>。</p><p><code>舞</code> / <code>霸</code> 版本需要跨全部 SD 版本拉取游玩记录（走水鱼 <code>/player/plate</code> 的版本列表，单请求完成），曲目表按「舞」牌口径判定，耗时略高于其他版本。进度表与完成表会按难度分别列出「余」的谱面数。</p><p>评价进度支持评价等级（如 <code>s</code>、<code>ss</code>、<code>sss</code>、<code>ap</code>、<code>fc</code>、<code>fs</code>、<code>fdx</code> 及其 <code>+</code> 写法），分类可选 <code>已完成</code>、<code>未完成</code>、<code>未开始</code> / <code>未游玩</code>。</p></div>`,17)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};